package __PACKAGE__;

import com.mojang.serialization.MapCodec;
import net.minecraft.core.particles.ParticleType;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;

/**
 * The particle type of the Sparkle systems (Minecraft 1.20.5 and later): it carries a {@link SparkleOptions} and is
 * sent to the players up to 512 blocks away.
 * Generated by the Sparkle plugin: do not edit, it is written again when the runtime is updated.
 */
public final class SparkleParticleType extends ParticleType<SparkleOptions> {
    public SparkleParticleType() {
        super(true);
    }

    @Override
    public MapCodec<SparkleOptions> codec() {
        return SparkleOptions.CODEC;
    }

    @Override
    public StreamCodec<? super RegistryFriendlyByteBuf, SparkleOptions> streamCodec() {
        return SparkleOptions.STREAM_CODEC;
    }
}
